-- Fiche Les verbes d'action (CE1) - anglais, notion 'en_verbes'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'ce1', 'english', 'Les verbes d''action', $fiche$
